\title{The Anti-Fibonacci Sequence: Quadratic Growth and Provable Avoidance of the Golden Ratio}
\author{Aristotle}
\date{2026-07-03}
\begin{document}
\begin{abstract}
The anti-Fibonacci sequence $A(0)=1,\ A(k+1)=A(k)+k$ (first terms $1,1,2,4,7,11,16,22,29,37,46,56,\dots$) admits the exact closed form $2A(k)+k=k^2+2$, i.e. $A(k)=1+\tfrac{k(k-1)}{2}$; grows quadratically with $A(k)/k^2\to\tfrac12$; and provably avoids the golden ratio $\varphi=\tfrac{1+\sqrt5}{2}$, since its consecutive ratio converges to $1$ and hence cannot converge to $\varphi$. The value set has natural density zero. We correct a folklore mis-estimate: the leading constant is $\tfrac12$, not $\tfrac14$, and the ratio converges monotonically to $1$ rather than oscillating.
\end{abstract}
\maketitle
\section{Introduction}
The Fibonacci recurrence produces exponential growth with $F(k+1)/F(k)\to\varphi$. Seeking a complementary object, the greedy rule forbidding each new term from equalling the sum of its two predecessors yields first differences $0,1,2,3,\dots$ and the sequence $1,1,2,4,7,11,16,\dots$; we define $A(0)=1,\ A(k+1)=A(k)+k$.
\section{Definitions}
\begin{definition} $A:\N\to\N$, $A(0)=1$, $A(k+1)=A(k)+k$. \end{definition}
\begin{lemma}[Positivity] $A(k)\ge1>0$ for all $k$. \end{lemma}
\begin{proof} Induction: $A(0)=1$; $A(k+1)=A(k)+k\ge A(k)\ge1$. \end{proof}
\section{Closed form}
\begin{theorem}\label{cf} $2A(k)+k=k^2+2$, i.e. $A(k)=1+\tfrac{k(k-1)}{2}$. \end{theorem}
\begin{proof} Induction. Base $2A(0)+0=2=0^2+2$. Step: $2A(k+1)+(k+1)=2(A(k)+k)+(k+1)=(2A(k)+k)+2k+1=k^2+2+2k+1=(k+1)^2+2$. \end{proof}
\begin{corollary}\label{real} $A(k)=(k^2-k+2)/2$. \end{corollary}
\section{Quadratic growth}
\begin{theorem} $\lim A(k)/k^2=1/2$. \end{theorem}
\begin{proof} $A(k)/k^2=\tfrac12-\tfrac{1}{2k}+\tfrac{1}{k^2}\to\tfrac12$. \end{proof}
\begin{corollary}\label{sub} $\lim k/A(k)=0$, since $k/A(k)=2k/(k^2-k+2)\le2/(k-1)\to0$. \end{corollary}
\section{Avoidance of the golden ratio}
\begin{theorem}\label{r1} $\lim A(k+1)/A(k)=1$. \end{theorem}
\begin{proof} $A(k+1)/A(k)=1+k/A(k)\to1$ by Corollary~\ref{sub}. \end{proof}
\begin{theorem} $A(k+1)/A(k)$ does not converge to $\varphi$. \end{theorem}
\begin{proof} Otherwise, with Theorem~\ref{r1}, uniqueness of limits gives $1=\varphi$, contradicting $\varphi>3/2>1$. \end{proof}
\section{Density}
\begin{proposition} $\{A(k)\}$ has natural density $0$. \end{proposition}
\begin{proof}[Sketch] $A(k)\le N \Rightarrow k\lesssim\sqrt{2N}$, so the count is $O(\sqrt N)$ and density $O(N^{-1/2})\to0$. \end{proof}
\section{Conclusion}
The anti-Fibonacci sequence is the polynomial-growth opposite of the Fibonacci sequence: exact closed form $1+\tfrac{k(k-1)}{2}$, growth $\sim k^2/2$, density-zero value set, and consecutive ratio $\to1\ne\varphi$.
\end{document}

