"""Numerical demonstrations for the Anti-Fibonacci sequence A(0)=1, A(k+1)=A(k)+k."""
from __future__ import annotations
from math import sqrt


def anti_fibonacci(n: int) -> list[int]:
    """Return [A(0), ..., A(n-1)] via the recurrence A(k+1)=A(k)+k."""
    seq: list[int] = []
    a: int = 1
    for k in range(n):
        seq.append(a)
        a = a + k
    return seq


def anti_fibonacci_closed(k: int) -> int:
    """Return A(k) via the closed form A(k)=1+k(k-1)//2."""
    return 1 + k * (k - 1) // 2


def golden_ratio() -> float:
    return (1.0 + sqrt(5.0)) / 2.0


def verify_closed_form(n: int) -> bool:
    seq = anti_fibonacci(n)
    return all(2 * seq[k] + k == k * k + 2 and seq[k] == anti_fibonacci_closed(k)
               for k in range(n))


def main() -> None:
    print('First 12 terms:', anti_fibonacci(12))
    print('Closed form verified for k<10000:', verify_closed_form(10000))
    for k in [10, 100, 1000, 10000, 100000, 1000000]:
        print(f'k={k:>8}  A(k)/k^2={anti_fibonacci_closed(k)/(k*k):.8f}'
              f'  A(k+1)/A(k)={anti_fibonacci_closed(k+1)/anti_fibonacci_closed(k):.8f}')
    print(f'golden phi = {golden_ratio():.6f}  (ratio -> 1, NOT phi)')


if __name__ == '__main__':
    main()

