def verify(n: int) -> bool:
    """Check recurrence == closed form and 2A(k)+k==k^2+2 for k<n."""
    seq = anti_fibonacci(n)
    for k in range(n):
        if seq[k] != anti_fibonacci_closed(k):
            return False
        if 2 * seq[k] + k != k * k + 2:
            return False
    return True


if __name__ == '__main__':
    print('First 12 terms:', anti_fibonacci(12))
    print('All identities hold for k<100000:', verify(100000))

